// Alternating exact finite subproblems for blind key + order + F mask recovery.
#define main known_key_main
#include "solver_generic.cpp"
#undef main
using Mask=array<int,R>;
struct State{Order o{};Key k{};Mask holds{};int score=BAD;};
struct Joint {
 const LM&lm;int longCol;array<array<int,W>,R> c{};array<int,R> z{};vector<pair<int,int>> zeros;
 int pen;array<array<int,30>,30> edge{};array<int,30> uni{};
 vector<uint8_t> values;vector<int> dp;vector<int8_t> prev;
 Joint(const Tape&t,int lc,const LM&m):lm(m),longCol(lc),values((size_t)(ALL+1)*W*R),dp((ALL+1)*W),prev((ALL+1)*W){auto col=columns(t,lc);for(int r=0;r<R;r++)for(int j=0;j<W;j++){c[r][j]=col[j][r+1];if(c[r][j]==0){z[r]|=1<<j;zeros.emplace_back(r,j);}}setPenalty(8*SCALE);}
 void setPenalty(int p){pen=p;for(int a=0;a<30;a++){uni[a]=lm.u[a%29]-(a==29?pen:0);for(int b=0;b<30;b++)edge[a][b]=lm.b[a%29][b%29]-(b==29?pen:0);}}
 int val(int x,int shift){int y=x-shift;if(y<0)y+=A;return y?y:29;}
 int direct(const State&s)const{int ph=0,score=0;for(int r=0;r<R;r++){int old=-1;for(int j:s.o){int y=0;if(s.holds[r]&(1<<j)){assert(!c[r][j]);}else{y=mod(c[r][j]-s.k[ph],A);if(!y)y=29;ph=(ph+1)%Q;}score+=old<0?uni[y]:edge[old][y];old=y;}}return score;}
 int illegals(const State&s)const{int ph=0,n=0;for(int r=0;r<R;r++)for(int j:s.o)if(!(s.holds[r]&(1<<j))){n+=(c[r][j]==s.k[ph]);ph=(ph+1)%Q;}return n;}
 int optimizeMask(State&s){constexpr int S=Q*A;array<int,S>d,n;d.fill(BAD);d[0]=0;vector<array<int16_t,S>>back(R*W);for(int i=0;i<R*W;i++){n.fill(BAD);back[i].fill(-1);int r=i/W,j=s.o[i%W],x=c[r][j];bool first=i%W==0;for(int st=0;st<S;st++)if(d[st]>BAD){int ph=st/A,old=st%A;auto put=[&](int y,int np,bool illegal){int ns=np*A+y,sc=d[st]+(first?lm.u[y]:lm.b[old][y])-(illegal?pen:0);if(sc>n[ns]){n[ns]=sc;back[i][ns]=st;}};int y=mod(x-s.k[ph],A);put(y,(ph+1)%Q,y==0);if(!x)put(0,ph,false);}d=n;}int st=max_element(d.begin(),d.end())-d.begin(),score=d[st];s.holds.fill(0);for(int i=R*W-1;i>=0;i--){int old=back[i][st];assert(old>=0);if(old/A==st/A)s.holds[i/W]|=1<<s.o[i%W];st=old;}assert(st==0);assert(score==direct(s));return score;}
 int optimizeKey(State&s){int u[Q][A]={},w[Q][A][A]={},constant=0,ph=0;for(int r=0;r<R;r++){int prevX=-1,prevPh=-1;bool prevHold=false;for(int j:s.o){bool hold=s.holds[r]&(1<<j);int x=c[r][j],curPh=ph;if(!hold){ph=(ph+1)%Q;for(int k=0;k<A;k++)if(x==k)u[curPh][k]-=pen;}if(prevX<0){if(hold)constant+=lm.u[0];else for(int k=0;k<A;k++)u[curPh][k]+=lm.u[mod(x-k,A)];}else if(hold){if(prevHold)constant+=lm.b[0][0];else for(int k=0;k<A;k++)u[prevPh][k]+=lm.b[mod(prevX-k,A)][0];}else if(prevHold){for(int k=0;k<A;k++)u[curPh][k]+=lm.b[0][mod(x-k,A)];}else{assert((prevPh+1)%Q==curPh);for(int a=0;a<A;a++)for(int b=0;b<A;b++)w[prevPh][a][b]+=lm.b[mod(prevX-a,A)][mod(x-b,A)];}prevX=x;prevPh=curPh;prevHold=hold;}}
  int best=BAD;Key bk{};for(int k0=0;k0<A;k0++){array<int,A>d,n;d.fill(BAD);d[k0]=u[0][k0];int back[Q][A]={};for(int j=1;j<Q;j++){n.fill(BAD);for(int a=0;a<A;a++)if(d[a]>BAD)for(int b=0;b<A;b++){int score=d[a]+w[j-1][a][b]+u[j][b];if(score>n[b]){n[b]=score;back[j][b]=a;}}d=n;}for(int a=0;a<A;a++){int sc=d[a]+w[Q-1][a][k0]+constant;if(sc>best){best=sc;bk[Q-1]=a;for(int j=Q-1;j>0;j--)bk[j-1]=back[j][bk[j]];assert(bk[0]==k0);}}}s.k=bk;assert(best==direct(s));return best;}
 uint8_t* v(int mask,int col){return values.data()+((size_t)mask*W+col)*R;}
 int optimizeOrder(State&s){array<int,R> start{};int ph=0;for(int r=0;r<R;r++){start[r]=ph;ph=mod(ph+W-__builtin_popcount((unsigned)s.holds[r]),Q);}int first=1<<longCol;for(int r=0;r<R;r++){int x=c[r][longCol];v(0,longCol)[r]=(s.holds[r]&first)?0:val(x,s.k[start[r]]);}for(int mask=first;mask<ALL;mask++)if(mask&first){int k=__builtin_popcount((unsigned)mask);int phase[R];for(int r=0;r<R;r++)phase[r]=(start[r]+k-__builtin_popcount((unsigned)(mask&s.holds[r])))%Q;for(unsigned bits=ALL^mask;bits;bits&=bits-1){int j=__builtin_ctz(bits);auto dst=v(mask,j);for(int r=0;r<R;r++)dst[r]=(s.holds[r]&(1<<j))?0:val(c[r][j],s.k[phase[r]]);}}
  fill(dp.begin(),dp.end(),BAD);int sc=0;for(int r=0;r<R;r++)sc+=uni[v(0,longCol)[r]];dp[first*W+longCol]=sc;for(int mask=first;mask<ALL;mask++)if(mask&first){for(unsigned a=mask;a;a&=a-1){int last=__builtin_ctz(a),score=dp[mask*W+last];if(score==BAD)continue;const auto x=v(mask^(1<<last),last);for(unsigned b=ALL^mask;b;b&=b-1){int j=__builtin_ctz(b);const auto y=v(mask,j);int cost=score;for(int r=0;r<R;r++)cost+=edge[x[r]][y[r]];int ix=(mask|(1<<j))*W+j;if(cost>dp[ix]){dp[ix]=cost;prev[ix]=last;}}}}
  int last=max_element(dp.begin()+ALL*W,dp.end())-(dp.begin()+ALL*W),best=dp[ALL*W+last],mask=ALL;for(int j=W-1;j>=0;j--){s.o[j]=last;int old=prev[mask*W+last];mask^=1<<last;last=old;}assert(s.o[0]==longCol&&mask==0);assert(best==direct(s));return best;}
 State randomState(mt19937&rng){State s;iota(s.o.begin(),s.o.end(),0);swap(s.o[0],s.o[longCol]);shuffle(s.o.begin()+1,s.o.end(),rng);double probability=uniform_real_distribution<double>(.15,.70)(rng);bernoulli_distribution h(probability);for(auto [r,j]:zeros)if(h(rng))s.holds[r]|=1<<j;for(int&k:s.k)k=rng()%A;return s;}
 State perturb(State s,mt19937&rng){int flips=zeros.empty()?0:1+rng()%min<size_t>(zeros.size(),8);for(int i=0;i<flips;i++){auto [r,j]=zeros[rng()%zeros.size()];s.holds[r]^=1<<j;}int swaps=rng()%4;for(int i=0;i<swaps;i++)swap(s.o[1+rng()%(W-1)],s.o[1+rng()%(W-1)]);return s;}
 State optimize(State s,int cycles){int last=direct(s);for(int i=0;i<cycles;i++){int k=optimizeKey(s);assert(k>=last);int o=optimizeOrder(s);assert(o>=k);int h=optimizeMask(s);assert(h>=o);if(h==last){last=h;break;}last=h;}s.score=last;return s;}
};
struct Case{string name;Tape c,p;Order o{};Key k{};LM lm;bool plant=false;};
Case makeCase(const vector<Source>&src,string mode){Case a;a.name=mode;if(mode=="original"){a.c=src[0].t;a.lm=model(src,"");return a;}a.plant=true;string n=mode=="control1"?"0_koan_1":"0_loss_of_divinity";auto it=find_if(src.begin(),src.end(),[&](const Source&s){return s.name==n;});a.p=sub(it->t,0,N);a.lm=model(src,n);iota(a.o.begin(),a.o.end(),0);mt19937 rng(mode=="control1"?3301:3302);shuffle(a.o.begin(),a.o.end(),rng);a.k=historical;if(mode=="control2")for(int&v:a.k)v=rng()%A;a.c=transpose(encrypt(a.p,a.k),a.o);return a;}
bool rotations(const Key&a,const Key&b){for(int j=0;j<Q;j++){bool eq=true;for(int k=0;k<Q;k++)eq&=(a[k]==b[(j+k)%Q]);if(eq)return true;}return false;}
int main(int argc,char**argv){if(argc!=7){cerr<<"usage: joint tapes.txt control1|control2|original split restarts cycles penalty_nats\n";return 1;}auto src=load(argv[1]);string mode=argv[2];int split=stoi(argv[3]),restarts=stoi(argv[4]),cycles=stoi(argv[5]),pen=lround(stod(argv[6])*SCALE);assert(split>=0&&split<W&&restarts>0&&cycles>0&&pen>0);Case a=makeCase(src,mode);Joint j(a.c,split,a.lm);j.setPenalty(pen);mt19937 rng(7701033+split*3301);State best;vector<State> pool;auto start=chrono::steady_clock::now();for(int t=0;t<restarts;t++){State s=t>0&&t%2&& !pool.empty()?j.perturb(pool[rng()%pool.size()],rng):j.randomState(rng);s=j.optimize(s,cycles);if(s.score>best.score){best=s;cout<<"IMPROVE "<<mode<<" split "<<split<<" restart "<<t<<" score "<<s.score<<" illegal "<<j.illegals(s)<<" order "<<ordstr(s.o)<<" key "<<ordstr(s.k)<<"\n"<<flush;}bool dup=false;for(auto&v:pool)if(v.o==s.o&&v.k==s.k&&v.holds==s.holds)dup=true;if(!dup){pool.push_back(s);sort(pool.begin(),pool.end(),[](auto&a,auto&b){return a.score>b.score;});if(pool.size()>8)pool.pop_back();}}
 cout<<"SOFT_WIN "<<mode<<" split "<<split<<" score "<<best.score<<" illegal "<<j.illegals(best)<<" order "<<ordstr(best.o)<<" key "<<ordstr(best.k)<<" seconds "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<"\n"<<flush;
 // Refine the 8 training-selected key cycles with the exact-F prefix beam, same physical split. No holdout used.
 Node bestLegal;Key legalKey{};for(auto&s:pool){Search sr(a.c,split,s.k,a.lm,256);Node n=sr.run(split);if(n.rank>bestLegal.rank){bestLegal=move(n);legalKey=s.k;}}
 if(bestLegal.rank==BAD){cout<<"NO_LEGAL "<<mode<<" split "<<split<<"\n";return 0;}Tape e=untranspose(a.c,bestLegal.o);auto tr=decode(sub(e,W,38*W),legalKey,a.lm);assert(tr.score==bestLegal.rank);auto ho=decode(sub(e,38*W,55*W),legalKey,a.lm,tr.phase);auto full=decode(e,legalKey,a.lm);
 cout<<"LEGAL_WIN "<<mode<<" split "<<split<<" score "<<tr.score<<" order "<<ordstr(bestLegal.o)<<" key "<<ordstr(legalKey)<<" start "<<tr.start<<" end "<<tr.phase<<" holdout "<<ho.score<<" full "<<full.score<<"\n";cout<<"TRAIN "<<enc(tr.plain)<<"\nHELD_BRIDGE "<<enc(ho.plain)<<"\nFULL "<<enc(full.plain)<<"\n";if(full.phase>=0)assert(transpose(encrypt(full.plain,legalKey,full.start),bestLegal.o)==a.c);if(a.plant)cout<<"PLANT "<<"order "<<(bestLegal.o==a.o)<<" key_rotation "<<rotations(legalKey,a.k)<<" train_exact "<<same(tr.plain,sub(a.p,W,38*W))<<" held_exact "<<(ho.phase<0?-1:same(sub(ho.plain,W,ho.plain.size()),sub(a.p,39*W,55*W)))<<" full_exact "<<same(full.plain,a.p)<<" true_order "<<ordstr(a.o)<<" true_key "<<ordstr(a.k)<<"\n";return 0;}
